-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 10
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 10 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Avaliação Prática', 'PENDENTE', v_aula, 'Atividade — Avaliação Prática (30 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/AVALIACAO-PRATICA.html', 30, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Identifique no caso o emissor, o receptor, a mensagem e o canal.', 0.5, 'Emissor: o supervisor de expedição. Receptor: o motorista (a equipe). Mensagem: a nova rota de coleta das transportadoras. Canal: o grupo de mensagens.', 'Nota cheia: os quatro elementos certos. Metade: dois ou três certos. Zero: um ou nenhum.'),
      (v_atividade, 1, 2, 'Explique qual elemento faltou para fechar o circuito da comunicação e o que o supervisor deveria ter pedido.', 0.5, 'Faltou o feedback (retorno do receptor), que fecha o circuito da comunicação. O supervisor deveria pedir confirmação de leitura e de entendimento (ex.: "confirme que entendeu o novo endereço"), e conferir se todos responderam.', 'Nota cheia: cita feedback e explica a confirmação. Metade: cita feedback sem dizer o que pedir, ou descreve a confirmação sem nomear o feedback. Zero: outro elemento.'),
      (v_atividade, 2, 1, 'Cite e classifique os três tipos de ruído que aparecem na situação.', 0.5, 'Ruído físico: barulho das empilhadeiras. Ruído semântico: o termo técnico "cross-docking" que o conferente não conhece. Ruído psicológico: o nervosismo depois da discussão.', 'Nota cheia: três ruídos identificados e classificados. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 2, 2, 'Proponha uma ação prática para reduzir cada um desses ruídos.', 0.5, 'Físico: conversar em local silencioso ou esperar parar as máquinas. Semântico: explicar o termo com palavras simples ou exemplo, conferir o entendimento. Psicológico: esperar o colega se acalmar, usar empatia e escuta ativa; formalizar por escrito se necessário.', 'Nota cheia: uma ação coerente para cada ruído. Metade: ações para dois ruídos. Zero: nenhuma ação coerente.'),
      (v_atividade, 3, 1, 'Escreva a frase que você diria ao colega usando o estilo assertivo.', 0.5, 'Frase que recusa com respeito e clareza, explica o motivo e oferece alternativa. Ex.: "Entendo que você precisa, mas hoje não consigo ficar porque tenho um compromisso. Posso te ajudar a falar com o supervisor ou trocar outro dia."', 'Nota cheia: firme, respeitosa e clara (diz não sem agredir e sem ceder). Metade: respeitosa mas vaga, ou clara mas sem respeito. Zero: passiva ou agressiva.'),
      (v_atividade, 3, 2, 'Explique como seria a resposta no estilo passivo e no estilo agressivo e por que eles prejudicam a equipe.', 0.5, 'Passivo: aceitar ficar mesmo sem poder, por medo de dizer não (gera sobrecarga e ressentimento). Agressivo: responder com grosseria ou acusação (gera conflito e quebra a confiança). Os dois prejudicam a equipe porque não resolvem o problema com respeito.', 'Nota cheia: descreve os dois estilos e o prejuízo. Metade: só um estilo, ou os dois sem o prejuízo. Zero: confunde os estilos.'),
      (v_atividade, 4, 1, 'Explique a função da memória RAM e do armazenamento (HDD/SSD) e como cada um contribui para a lentidão.', 0.5, 'A RAM guarda temporariamente os programas e dados em uso; com 4 GB, WMS e planilhas abertos juntos esgotam a memória e o sistema fica lento (usa o disco como memória). O HDD é mecânico e lento para ler e gravar; o SSD é eletrônico e muito mais rápido, por isso o HDD deixa abrir programas e arquivos demorado.', 'Nota cheia: explica a função de cada um e a relação com a lentidão. Metade: só um dos dois. Zero: confunde RAM com armazenamento.'),
      (v_atividade, 4, 2, 'Recomende um upgrade e justifique o ganho que ele traz para o trabalho do setor.', 0.5, 'Trocar o HDD por SSD e aumentar a RAM (ex.: para 8 GB ou mais). Ganho: o computador e o WMS abrem mais rápido, permitem várias janelas abertas, reduzindo o tempo de espera e aumentando a produtividade do setor.', 'Nota cheia: upgrade coerente e justificado com o ganho no trabalho. Metade: upgrade certo sem justificativa. Zero: recomendação sem relação (ex.: trocar monitor).'),
      (v_atividade, 5, 1, 'Proponha uma estrutura de pastas (com subpastas) para o setor.', 0.5, 'Estrutura hierárquica por setor/assunto e período. Ex.: Documentos > Expedicao > 2026 > 10-Outubro; Documentos > Inventario > 2026; Documentos > Relatorios; Documentos > Imagens.', 'Nota cheia: pastas e subpastas lógicas que separam os tipos de arquivo. Metade: pastas sem subpastas ou critério confuso. Zero: sem estrutura.'),
      (v_atividade, 5, 2, 'Renomeie três dos arquivos do contexto seguindo um padrão profissional de nomenclatura e explique o padrão usado.', 0.5, 'Padrão com tipo/assunto, data (AAAA-MM-DD) e versão, sem espaços, acentos ou palavras como "final"/"novo"/"agora". Ex.: "2026-10-01_Relatorio-Expedicao_v02.xlsx", "2026-10-01_Inventario-Mensal_v01.xlsx", "2026-10-01_Foto-Doca-03.jpg".', 'Nota cheia: três nomes no padrão e explicação. Metade: nomes melhores mas sem padrão consistente ou sem explicação. Zero: mantém nomes vagos.'),
      (v_atividade, 6, 1, 'Explique o papel do sistema operacional e do driver na comunicação entre o computador e a impressora.', 0.5, 'O sistema operacional gerencia o hardware e intermedeia programas e dispositivos; o driver é o programa que ensina o sistema a se comunicar com aquele periférico específico. Sem o driver certo, o SO não sabe enviar a impressão.', 'Nota cheia: papel do SO e do driver. Metade: só um. Zero: errado.'),
      (v_atividade, 6, 2, 'Descreva, em passos numerados, como você diagnosticaria e resolveria o problema.', 0.5, '1) Conferir cabo, energia, etiquetas e se a impressora está ligada. 2) Ver se o sistema reconheceu o dispositivo. 3) Instalar ou atualizar o driver do fabricante. 4) Definir como impressora padrão ou escolher a impressora certa. 5) Imprimir uma página de teste. 6) Se persistir, chamar o suporte de TI.', 'Nota cheia: passos numerados, em ordem lógica, incluindo driver e teste. Metade: poucos passos ou sem o driver. Zero: sem procedimento.'),
      (v_atividade, 7, 1, 'Escreva a frase de busca completa que você digitaria no buscador.', 0.5, 'armazenagem "produtos químicos" filetype:pdf site:gov.br -alimentos (ordem pode variar; aceitar norma/armazenamento como palavras-chave).', 'Nota cheia: usa filetype:pdf, site:gov.br, exclusão com "-" e palavras-chave (aspas são um extra). Metade: dois dos três operadores. Zero: busca sem operadores.'),
      (v_atividade, 7, 2, 'Explique a função de cada operador usado na sua busca.', 0.5, 'filetype:pdf limita a arquivos PDF; site:gov.br limita a sites do governo; o sinal de menos exclui resultados com a palavra "alimentos"; as aspas buscam a expressão exata.', 'Nota cheia: explica corretamente cada operador usado. Metade: explica parte. Zero: explicações erradas.'),
      (v_atividade, 8, 1, 'Avalie o blog usando pelo menos três critérios do teste CRAAP.', 0.5, 'Autoridade: sem autor, não dá para saber quem escreveu. Atualidade (Currency): sem data. Precisão/Exatidão: afirmação genérica sem fonte e incorreta (a capacidade varia por modelo). Propósito: cheio de anúncios, pode ter interesse comercial. Conclusão: fonte não confiável.', 'Nota cheia: três critérios aplicados ao blog. Metade: um ou dois. Zero: nenhum critério.'),
      (v_atividade, 8, 2, 'Indique onde você buscaria uma informação confiável sobre o assunto e por quê.', 0.5, 'No manual do fabricante da empilhadeira, na placa de capacidade do equipamento, em normas técnicas/regulamentadoras (NR-11) ou com o técnico de segurança, porque têm autoria identificada, são oficiais e específicos do equipamento.', 'Nota cheia: fonte confiável e justificativa. Metade: fonte sem justificativa. Zero: outra fonte não confiável.'),
      (v_atividade, 9, 1, 'Explique o que a Lei 9.610/98 diz sobre esse uso e por que "disponível na internet não é público".', 0.5, 'A Lei 9.610/98 (direitos autorais) protege textos e imagens desde a criação, mesmo sem registro; para usar é preciso autorização do autor ou licença. Estar disponível na internet não significa estar em domínio público nem liberado para uso.', 'Nota cheia: cita a proteção da lei e explica "disponível não é público". Metade: só uma parte. Zero: diz que pode usar livremente.'),
      (v_atividade, 9, 2, 'Explique como usar a foto (licenças Creative Commons) e o parágrafo (citação) de forma correta.', 0.5, 'Foto: usar imagem com licença que permita o uso (ex.: Creative Commons CC BY, dando crédito ao autor; respeitar NC se for uso comercial) ou de banco de imagens livre, ou tirar a própria foto. Parágrafo: fazer citação direta entre aspas com autor, ano e fonte (ou paráfrase com referência), sem plágio.', 'Nota cheia: foto com licença/crédito e parágrafo com citação. Metade: só um. Zero: copiar sem crédito.'),
      (v_atividade, 10, 1, 'Escreva o assunto do e-mail.', 0.3, 'Assunto específico e informativo. Ex.: "Atraso na coleta do pedido – nova previsão 02/10 às 9h".', 'Nota cheia: assunto claro, objetivo, que identifica o tema (atraso + coleta + nova data). Metade: claro mas incompleto. Zero: vago ("Aviso", "Urgente") ou em branco.'),
      (v_atividade, 10, 2, 'Escreva o corpo completo do e-mail, da saudação ao fechamento com assinatura.', 0.7, 'Saudação formal; informar o atraso da coleta de hoje às 14h e o motivo (problema no caminhão da transportadora); nova previsão (amanhã às 9h); pedido de desculpas e disponibilidade para dúvidas; fechamento cordial; assinatura com nome, cargo, empresa e contato. Linguagem formal, sem CAPS LOCK e sem gírias.', 'Nota cheia: todas as partes (saudação, fato, motivo, nova previsão, fechamento, assinatura) com linguagem formal. Metade: falta uma ou duas partes ou linguagem informal. Zero: não comunica o atraso e a nova data.'),
      (v_atividade, 11, 1, 'Indique em qual campo (Para, CC ou CCO) você colocaria os endereços dos clientes e explique a diferença entre os três campos.', 0.5, 'Campo CCO (cópia oculta). Para: destinatário principal; CC: cópia visível a todos; CCO: cópia oculta, ninguém vê os outros endereços.', 'Nota cheia: CCO e a diferença dos três campos. Metade: CCO sem explicar os campos, ou explica os campos sem escolher CCO. Zero: escolhe Para ou CC.'),
      (v_atividade, 11, 2, 'Explique a relação dessa escolha com a LGPD.', 0.5, 'O e-mail é dado pessoal; expor os endereços de 40 clientes de empresas diferentes aos demais seria compartilhar dados sem necessidade nem consentimento, o que a LGPD proíbe. O CCO protege esses dados.', 'Nota cheia: e-mail como dado pessoal e proteção contra exposição. Metade: cita a LGPD de forma genérica. Zero: sem relação.'),
      (v_atividade, 12, 1, 'Indique a permissão (leitor, comentador ou editor) de cada pessoa e justifique.', 0.6, 'Supervisor: editor (precisa corrigir os dados). Auditor externo: leitor (só confere, não pode alterar). Estagiário: comentador (deixa observações sem alterar). Princípio do menor privilégio.', 'Nota cheia: três permissões certas e justificadas. Metade: duas certas, ou três sem justificativa. Zero: uma ou nenhuma.'),
      (v_atividade, 12, 2, 'Explique por que não se deve compartilhar essa planilha por link público.', 0.4, 'Qualquer pessoa com o link teria acesso aos dados do inventário (informação interna e estratégica), sem controle de quem acessa, podendo vazar ou ser alterada; perde-se o rastreio de quem viu/alterou.', 'Nota cheia: falta de controle de acesso e risco de vazamento. Metade: só "é perigoso" sem explicar. Zero: em branco ou errado.'),
      (v_atividade, 13, 1, 'Aponte três sinais de que a mensagem é phishing.', 0.5, 'Urgência e ameaça ("será bloqueada em 2 horas"); pedido de senha (empresas não pedem senha por e-mail); remetente falso/estranho com "0" no lugar de "o" ("banc0"); link para clicar; mensagem genérica.', 'Nota cheia: três sinais. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 13, 2, 'Descreva o que você deve fazer (e o que não deve fazer) com essa mensagem.', 0.5, 'Não clicar no link, não responder e não informar senha; não abrir anexos; reportar à equipe de TI/segurança (incidente) e apagar ou marcar como phishing; se tiver dúvida, contatar a instituição pelo canal oficial.', 'Nota cheia: o que não fazer e reportar à TI. Metade: só um dos lados. Zero: clicar ou responder.'),
      (v_atividade, 14, 1, 'Indique qual pilar (confidencialidade, integridade ou disponibilidade) foi violado em cada incidente.', 0.6, '(1) Alteração indevida da planilha: integridade. (2) Servidor fora do ar: disponibilidade. (3) Lista de salários vazada: confidencialidade.', 'Nota cheia: três certas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 14, 2, 'Proponha uma medida de proteção para cada incidente.', 0.4, '(1) Controle de permissões (só quem precisa edita), histórico de versões/registro de alterações, proteção de células. (2) Backup, redundância, manutenção preventiva, plano de contingência. (3) Controle de acesso, criptografia, classificação da informação, conscientização e não compartilhar em grupos.', 'Nota cheia: medida coerente para os três. Metade: para dois. Zero: medidas sem relação.'),
      (v_atividade, 15, 1, 'Classifique os dados coletados em dados pessoais comuns e dados pessoais sensíveis.', 0.5, 'Comuns: nome, CPF, telefone, endereço. Sensível: biometria (impressão digital).', 'Nota cheia: classificação correta, com a biometria como sensível. Metade: biometria certa com algum comum errado. Zero: biometria como comum.'),
      (v_atividade, 15, 2, 'Explique dois cuidados que a empresa deve ter com esses dados segundo a LGPD.', 0.5, 'Coletar só o necessário e para finalidade definida (controle de acesso); informar o titular e ter base legal/consentimento para o dado sensível; guardar com segurança (acesso restrito, criptografia); não guardar para sempre (eliminar quando a finalidade acabar); não compartilhar sem necessidade.', 'Nota cheia: dois cuidados corretos. Metade: um. Zero: nenhum.'),
      (v_atividade, 16, 1, 'Explique por que usar estilos (Título 1, Título 2) em vez de formatação manual.', 0.5, 'Os estilos marcam o nível de cada título; isso permite gerar o sumário automático, manter a formatação padronizada e alterar todos os títulos de uma vez (alteração global). A formatação manual não é reconhecida como título.', 'Nota cheia: sumário automático e padronização/alteração global. Metade: só um. Zero: errado.'),
      (v_atividade, 16, 2, 'Descreva os passos para inserir o sumário automático e atualizá-lo depois de mudar o texto.', 0.5, '1) Aplicar Título 1 e Título 2 aos títulos. 2) Posicionar o cursor no início (após a capa). 3) Referências > Sumário (Inserir índice no LibreOffice). 4) Depois de editar, clicar com o botão direito no sumário > Atualizar campo/índice (atualizar o sumário inteiro).', 'Nota cheia: inserir e atualizar corretamente. Metade: só inserir ou só atualizar. Zero: sem passos.'),
      (v_atividade, 17, 1, 'Descreva a configuração da página: tamanho do papel e as quatro margens.', 0.5, 'Papel A4; margens superior e esquerda 3 cm, inferior e direita 2 cm.', 'Nota cheia: A4 e as quatro margens certas. Metade: A4 com margens parcialmente certas. Zero: margens erradas.'),
      (v_atividade, 17, 2, 'Descreva a formatação dos parágrafos: fonte, tamanho, espaçamento entre linhas, alinhamento e recuo.', 0.5, 'Fonte Arial ou Times New Roman, tamanho 12; espaçamento 1,5 entre linhas; alinhamento justificado; recuo de primeira linha (1,25 cm).', 'Nota cheia: fonte, tamanho, 1,5, justificado e recuo. Metade: três ou quatro itens. Zero: dois ou menos.'),
      (v_atividade, 18, 1, 'Explique como funciona o controle de alterações e o que significa aceitar ou rejeitar uma alteração.', 0.5, 'Com o controle de alterações ligado, cada inclusão, exclusão ou mudança do revisor fica marcada (cor, nome, data) sem apagar o original; o autor aceita (a alteração passa a valer) ou rejeita (volta ao texto original) cada mudança. Comentários podem explicar as sugestões.', 'Nota cheia: explica a marcação e aceitar/rejeitar. Metade: só um. Zero: errado.'),
      (v_atividade, 18, 2, 'Explique quando enviar o arquivo em .docx e quando enviar em PDF, com uma vantagem de cada.', 0.5, '.docx enquanto o documento ainda é editado/revisado (vantagem: permite editar e revisar). PDF para a versão final enviada ao cliente (vantagem: mantém a formatação em qualquer computador, não é alterado facilmente e é mais profissional; cuidar dos metadados e comentários).', 'Nota cheia: quando usar cada um com uma vantagem. Metade: só um formato ou sem vantagem. Zero: inverte.'),
      (v_atividade, 19, 1, 'Aponte os problemas do trecho quanto a clareza, concisão, objetividade e impessoalidade.', 0.4, 'Falta impessoalidade ("achamos"); falta objetividade e há juízo de valor/culpa ("pessoal que não cuida direito", "desastre total"); falta clareza e precisão (sem data, sem o defeito, "uma eternidade" em vez do tempo); linguagem informal ("pra").', 'Nota cheia: aponta problemas ligados às quatro qualidades. Metade: duas ou três. Zero: nenhuma.'),
      (v_atividade, 19, 2, 'Reescreva o trecho em linguagem técnica (você pode criar dados fictícios, como data e tempo parado).', 0.6, 'Ex.: "Em 30/09/2026, a empilhadeira EMP-02 apresentou falha no sistema hidráulico, a segunda ocorrência no mês. O equipamento ficou parado por 6 horas. Recomenda-se verificar o cumprimento do checklist diário de inspeção."', 'Nota cheia: impessoal, objetivo, com dados concretos e sem juízo de valor. Metade: melhora parcial (ainda com opinião ou vago). Zero: mantém os problemas.'),
      (v_atividade, 20, 1, 'Cite, na ordem correta, as partes que uma ata deve ter.', 0.4, 'Cabeçalho (título, data, hora, local) → abertura e leitura da pauta (participantes) → discussões e deliberações → encerramento e assinaturas.', 'Nota cheia: partes na ordem certa. Metade: partes certas fora de ordem ou faltando uma. Zero: errado.'),
      (v_atividade, 20, 2, 'Redija a ata desta reunião (pode completar com dados fictícios).', 0.6, 'Texto corrido, sem parágrafos e sem rasuras, verbos no pretérito, números por extenso quando possível. Ex.: "Ata da reunião de segurança do armazém. Ao primeiro dia do mês de outubro de dois mil e vinte e seis, às oito horas, na sala de treinamento da Distribuidora Vale Sul Logística, reuniram-se o gerente ..., a técnica de segurança ... e cinco operadores ... Deliberou-se que o uso de colete refletivo passa a ser obrigatório na doca. Nada mais havendo a tratar, encerrou-se a reunião, e eu, ..., lavrei a presente ata, que vai assinada por todos."', 'Nota cheia: data, hora, local, participantes, deliberação do colete, encerramento e assinaturas, em linguagem formal. Metade: falta parte importante. Zero: não é uma ata.'),
      (v_atividade, 21, 1, 'Escreva pelo menos cinco passos numerados do procedimento, com os verbos no infinitivo ou no imperativo.', 0.6, 'Ex.: 1. Conferir a nota fiscal com o pedido de compra. 2. Verificar a integridade das embalagens. 3. Contar os volumes e conferir os itens. 4. Registrar divergências e avarias. 5. Dar entrada no sistema (WMS). 6. Encaminhar para a área de armazenagem.', 'Nota cheia: cinco passos ou mais, numerados, em ordem lógica, verbos no infinitivo/imperativo. Metade: menos de cinco passos ou verbos em outro tempo. Zero: sem passos.'),
      (v_atividade, 21, 2, 'Indique os alertas de segurança e os EPIs que devem constar no POP.', 0.4, 'Alertas: cuidado com empilhadeiras e paleteiras em movimento, faixa de pedestre, não ficar sob cargas suspensas, postura ao levantar peso. EPIs: botina/calçado de segurança, luvas, colete refletivo, capacete quando exigido.', 'Nota cheia: pelo menos um alerta e dois EPIs coerentes. Metade: só alertas ou só EPIs. Zero: nenhum.'),
      (v_atividade, 22, 1, 'Escreva a fórmula da célula D2 e explique por que usar referências de células em vez de digitar os números.', 0.5, '=B2*C2. Com referências, a fórmula se atualiza quando os valores mudam e pode ser copiada para as outras linhas (referência relativa ajusta para B3*C3...).', 'Nota cheia: fórmula certa e explicação. Metade: só a fórmula ou só a explicação. Zero: fórmula errada e sem explicação.'),
      (v_atividade, 22, 2, 'Escreva as fórmulas do valor total do estoque (soma da coluna D) e da média dos preços unitários.', 0.5, 'Total: =SOMA(D2:D51). Média dos preços: =MÉDIA(C2:C51).', 'Nota cheia: as duas certas (intervalo com dois pontos). Metade: uma certa. Zero: nenhuma.'),
      (v_atividade, 23, 1, 'Escreva a fórmula da célula E2 com a função SE e explique cada parte.', 0.4, '=SE(B2<20;"Repor";"OK"). Teste lógico B2<20; valor se verdadeiro "Repor"; valor se falso "OK"; texto entre aspas e argumentos separados por ponto e vírgula.', 'Nota cheia: fórmula certa e partes explicadas. Metade: fórmula certa sem explicação ou com pequeno erro de sintaxe. Zero: errada.'),
      (v_atividade, 23, 2, 'Escreva a fórmula com CONT.SE que conta quantos produtos estão com "Repor".', 0.3, '=CONT.SE(E2:E51;"Repor").', 'Nota cheia: certa. Metade: lógica certa com erro de sintaxe ou intervalo. Zero: errada.'),
      (v_atividade, 23, 3, 'Escreva a fórmula com CONT.VALORES que conta quantos produtos estão cadastrados na coluna A.', 0.3, '=CONT.VALORES(A2:A51).', 'Nota cheia: certa. Metade: lógica certa com erro de intervalo. Zero: usa outra função ou errada.'),
      (v_atividade, 24, 1, 'Explique a causa de cada um dos dois problemas.', 0.5, 'Tudo na coluna A: o separador do CSV (ponto e vírgula, comum no Brasil, ou vírgula) não foi reconhecido na abertura. Acentos quebrados: codificação errada; o arquivo é UTF-8 e foi lido em outra codificação.', 'Nota cheia: as duas causas. Metade: uma. Zero: nenhuma.'),
      (v_atividade, 24, 2, 'Descreva os passos para importar o arquivo corretamente.', 0.5, 'Usar Dados > Obter dados / De Texto/CSV (ou abrir pelo assistente de importação no LibreOffice), escolher a origem/codificação UTF-8, escolher o delimitador ponto e vírgula, conferir a prévia e carregar. Alternativa: Dados > Texto para colunas com o delimitador certo.', 'Nota cheia: importação com codificação UTF-8 e delimitador. Metade: só um dos ajustes. Zero: sem procedimento.'),
      (v_atividade, 25, 1, 'Indique o tipo de gráfico mais adequado para cada caso e justifique.', 0.6, '(1) Linhas: mostra evolução/tendência no tempo. (2) Pizza (setores): participação no total, poucas categorias (quatro), soma 100%. (3) Colunas ou barras: compara quantidades entre categorias (barras horizontais ajudam com nomes longos).', 'Nota cheia: três tipos certos e justificados. Metade: dois certos, ou três sem justificativa. Zero: um ou nenhum.'),
      (v_atividade, 25, 2, 'Cite os elementos que todo gráfico profissional deve ter para ser entendido sozinho.', 0.4, 'Título claro, rótulos e unidades nos eixos, legenda quando houver mais de uma série, rótulos de dados quando ajudam, fonte dos dados.', 'Nota cheia: título, eixos/unidades e legenda. Metade: dois elementos. Zero: um ou nenhum.'),
      (v_atividade, 26, 1, 'Explique como criar uma lista suspensa para a coluna de cidades e qual problema ela resolve.', 0.5, 'Criar uma lista com as cidades válidas; selecionar a coluna de cidades; Dados > Validação de Dados > Permitir: Lista > Origem: a lista; com mensagem de erro. Resolve a digitação diferente da mesma cidade, padronizando os dados para filtros, contagens e gráficos.', 'Nota cheia: passos e problema resolvido. Metade: só um. Zero: errado.'),
      (v_atividade, 26, 2, 'Descreva uma validação para a coluna de quantidades que impeça valores inválidos.', 0.5, 'Selecionar a coluna de quantidades; Validação de Dados > Permitir: Número inteiro > maior ou igual a 0 (ou entre 0 e um limite); alerta de erro para bloquear valores negativos.', 'Nota cheia: validação de número inteiro com limite mínimo e alerta. Metade: ideia certa sem os passos. Zero: errado.'),
      (v_atividade, 27, 1, 'Explique por que o eixo truncado e o efeito 3D distorcem a leitura dos dados.', 0.5, 'O eixo começando em 950 aumenta visualmente a diferença (20 entregas, cerca de 2%, parece o dobro); o 3D distorce a altura e a perspectiva das colunas e dificulta a leitura dos valores. Isso engana a diretoria e tira a credibilidade.', 'Nota cheia: explica os dois efeitos. Metade: só um. Zero: não vê problema.'),
      (v_atividade, 27, 2, 'Descreva como refazer o gráfico de forma honesta e acessível.', 0.5, 'Gráfico de colunas 2D com eixo vertical começando em zero, título claro, rótulos de dados, unidades, cores com bom contraste (sem depender só da cor) e fonte dos dados.', 'Nota cheia: eixo em zero, sem 3D e um cuidado de acessibilidade. Metade: só eixo ou só 3D. Zero: não corrige.'),
      (v_atividade, 28, 1, 'Descreva a estrutura da narrativa (situação, complicação, resolução e conclusão) aplicada a esse projeto.', 0.5, 'Situação: como estava a expedição (dados de atrasos). Complicação: o problema e seu impacto (atrasos, custos, clientes insatisfeitos). Resolução: as ações do projeto. Conclusão: resultados (redução dos atrasos com números) e próximos passos.', 'Nota cheia: quatro etapas aplicadas ao projeto. Metade: etapas sem aplicação ou faltando uma. Zero: sem estrutura.'),
      (v_atividade, 28, 2, 'Explique para que serve o slide mestre e como garantir hierarquia visual e contraste nos slides.', 0.5, 'O slide mestre define o padrão (fontes, cores, logotipo, posições) de todos os slides; mudar nele muda em todos. Hierarquia: título maior que o texto, poucas fontes, pouco texto por slide; contraste: texto escuro em fundo claro (ou o contrário).', 'Nota cheia: função do mestre e hierarquia/contraste. Metade: só um. Zero: errado.'),
      (v_atividade, 29, 1, 'Explique a diferença entre colar o gráfico como imagem estática e como objeto vinculado.', 0.5, 'Imagem estática é uma "foto" do gráfico: não muda quando a planilha muda. Objeto vinculado mantém a ligação com a planilha e é atualizado quando os dados mudam.', 'Nota cheia: diferença correta. Metade: explica só um. Zero: inverte.'),
      (v_atividade, 29, 2, 'Descreva os passos para inserir o gráfico vinculado e o cuidado necessário ao mover os arquivos.', 0.5, 'Copiar o gráfico na planilha; no slide, Colar especial > Colar vínculo (ou Inserir > Objeto > Criar do arquivo > Vincular); atualizar os vínculos ao abrir. Cuidado: manter a planilha no mesmo local (ou na nuvem); se mover ou renomear, o vínculo quebra e precisa ser refeito.', 'Nota cheia: passos e cuidado com o local do arquivo. Metade: só um. Zero: errado.'),
      (v_atividade, 30, 1, 'Explique três cuidados de postura e oratória durante a apresentação.', 0.5, 'Manter contato visual com o público, postura ereta e gestos naturais, voz clara e ritmo adequado, não ler os slides, ensaiar antes e controlar o tempo, usar o modo apresentador.', 'Nota cheia: três cuidados. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 30, 2, 'Explique os cuidados com os dados pessoais (LGPD) e com a foto (direitos autorais) nos slides.', 0.5, 'Não mostrar nome e CPF dos motoristas (dados pessoais, LGPD): usar dados agregados ou anonimizados (Motorista A, B). A foto: usar imagem com licença que permita o uso e dar crédito, ou foto própria, respeitando a Lei 9.610/98.', 'Nota cheia: os dois cuidados. Metade: só um. Zero: nenhum.');
end $$;
